package io.github.jackotom.hongguo.android;
import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
/** Production pending RPC, Plan validation and playback-only recovery classifier. */
public final class PlaybackResolutionSourceTest {
 static final String SID="1234567890123456789",VID="2345678901234567890",URL="https://v3-reading.qznovelvod.com/recorded-resolution.mp4";static Method resolve,classify;static int checks,groups;static MainActivity host=new MainActivity();
 interface Run{void run()throws Exception;}static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}static void group(String label,Run run)throws Exception{run.run();groups++;System.out.println("PASS "+label);}
 static Exception reject(Run run)throws Exception{checks++;try{run.run();throw new AssertionError("expected failure");}catch(Exception e){return e;}}
 static PlaybackSources.Plan lookup(String q,int ceiling,boolean fresh)throws Exception{try{return(PlaybackSources.Plan)resolve.invoke(null,SID,VID,q,ceiling,fresh,false);}catch(InvocationTargetException e){throw(Exception)e.getCause();}}
 static boolean eligible(Exception e)throws Exception{return(Boolean)classify.invoke(null,e);}
 static JSONArray args(String script)throws Exception{return new JSONArray("["+script.substring(script.lastIndexOf('(')+1,script.length()-1)+"]");}
 static JSONObject model(String q,int shortEdge,int cap)throws Exception{JSONObject p=new JSONObject().put("url",URL).put("seriesId",SID).put("vid",VID).put("source","app").put("requestedQuality",q);if(shortEdge>0)p.put("width",shortEdge).put("height",shortEdge*2);if(cap>0)p.put("playbackCeiling",cap);return p;}
 static JSONObject envelope(JSONArray a)throws Exception{JSONObject p=new JSONObject().put("requestId",a.getString(0)).put("seriesId",a.getString(1)).put("vid",a.getString(2)).put("requestedQuality",a.getString(3));if(a.length()>4)p.put("playbackCeiling",a.getInt(4));return p;}
 static void callback(java.util.function.Consumer<JSONArray> reply){host.callback=script->{try{reply.accept(args(script));}catch(Exception e){throw new RuntimeException(e);}};}
 static void success(JSONArray a,int shortEdge){try{PlaybackSources.result(envelope(a).put("playInfo",model(a.getString(3),shortEdge,a.length()>4?a.getInt(4):0)));}catch(Exception e){throw new RuntimeException(e);}}
 public static void main(String[]args)throws Exception{
  try{resolve=PlaybackSources.class.getDeclaredMethod("resolvePlayback",String.class,String.class,String.class,int.class,boolean.class,boolean.class);classify=PlaybackSources.class.getDeclaredMethod("canRecoverPlayback",Exception.class);}catch(NoSuchMethodException absent){System.out.println("FAIL missing actual bounded fresh playback source API / resolution ceiling");System.exit(1);return;}
  PlaybackSources.attach(host);
  try{
   group("timed-out native waiter aborts only its matching registered model job",()->{
    List<String> scripts=new ArrayList<>();host.callback=scripts::add;Method attempt=PlaybackSources.class.getDeclaredMethod("resolveAppAttempt",String.class,String.class,String.class,long.class,int.class);attempt.setAccessible(true);
    Exception failure=reject(()->{try{attempt.invoke(null,SID,VID,"auto",25L,0);}catch(InvocationTargetException e){throw(Exception)e.getCause();}});
    check(failure.getMessage().contains("超时"),"actual future timeout is preserved");
    check(scripts.size()==2&&scripts.get(1).contains("__androidAppCancelResolve"),"native waiter cancels matching JavaScript model job");
    check(args(scripts.get(0)).getString(0).equals(args(scripts.get(1)).getString(0)),"cancel uses original opaque operation ID");
    Field requests=PlaybackSources.class.getDeclaredField("pending");requests.setAccessible(true);check(((Map<?,?>)requests.get(null)).isEmpty(),"timed out pending request removed");
   });
   group("interrupted native waiter cancels registered job without a later reply",()->{
    List<String>scripts=Collections.synchronizedList(new ArrayList<>());java.util.concurrent.CountDownLatch started=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicReference<Throwable>failure=new java.util.concurrent.atomic.AtomicReference<>();java.util.concurrent.atomic.AtomicBoolean interrupted=new java.util.concurrent.atomic.AtomicBoolean();
    host.callback=script->{scripts.add(script);if(script.contains("__androidAppResolve("))started.countDown();};Method attempt=PlaybackSources.class.getDeclaredMethod("resolveAppAttempt",String.class,String.class,String.class,long.class,int.class);attempt.setAccessible(true);
    Thread thread=new Thread(()->{try{attempt.invoke(null,SID,VID,"auto",1000L,0);}catch(Throwable e){failure.set(e instanceof InvocationTargetException?e.getCause():e);interrupted.set(Thread.currentThread().isInterrupted());}});thread.start();check(started.await(1,java.util.concurrent.TimeUnit.SECONDS),"request started");thread.interrupt();thread.join(1000);
    check(!thread.isAlive()&&failure.get() instanceof InterruptedException&&interrupted.get(),"interruption retained and waiter stopped");
    check(scripts.size()==2&&scripts.get(1).contains("__androidAppCancelResolve"),"interrupted waiter stops JavaScript and native operation");
    check(args(scripts.get(0)).getString(0).equals(args(scripts.get(1)).getString(0)),"interruption never cancels a new selection");
   });
   group("fresh same URL performs distinct opaque requests and retains measured cap",()->{List<JSONArray>calls=new ArrayList<>();callback(a->{calls.add(a);success(a,720);});PlaybackSources.Plan a=lookup("720p",1079,true),b=lookup("720p",1079,true);check(calls.size()==2&&!calls.get(0).getString(0).equals(calls.get(1).getString(0)),"new opaque lookup even same URL");check(a.width==720&&b.width==720&&a.json().getInt("playbackCeiling")==1079,"real Plan stores measured cap");});
   group("all fallback stages and cache namespaces remain separate",()->{for(String q:new String[]{"480p","360p"}){int n=Integer.parseInt(q.substring(0,q.length()-1));callback(a->success(a,n));PlaybackSources.Plan p=PlaybackSources.resolve(SID,VID,q);check(p.width==n&&p.requestedQuality.equals(q),"new internal quality resolves");check(!MediaQuality.cacheVid(VID,q).equals(MediaQuality.cacheVid(VID,"auto")),"separate quality cache namespace");}});
   group("high or unknown candidate and high variant never masquerade as lower resolution",()->{for(int shortEdge:new int[]{0,1080}){callback(a->success(a,shortEdge));Exception e=reject(()->lookup("720p",1079,false));check(eligible(e),"valid missing/larger resolution is typed unavailable");}JSONObject p=model("720p",720,1079);p.put("variants",new JSONArray().put(model("720p",1080,1079)));Exception e=reject(()->PlaybackSources.register(p,VID,false));check(eligible(e),"all variants obey cap");});
   group("callback ceiling and identity mismatches reject without becoming recoverable",()->{callback(a->{try{PlaybackSources.result(envelope(a).put("playbackCeiling",719).put("playInfo",model("720p",720,1079)));}catch(Exception expected){}});check(!eligible(reject(()->lookup("720p",1079,true))),"ceiling mismatch is terminal");callback(a->{try{PlaybackSources.result(envelope(a).put("vid","999999").put("playInfo",model("720p",720,1079)));}catch(Exception expected){}});check(!eligible(reject(()->lookup("720p",1079,true))),"identity mismatch is terminal");});
   group("fresh empty model may reconnect but lower-quality classifier remains strict",()->{List<JSONArray>calls=new ArrayList<>();callback(a->{calls.add(a);try{PlaybackSources.result(envelope(a).put("error","fixture empty response").put("errorCode","APP_EMPTY_RESPONSE"));}catch(Exception e){throw new RuntimeException(e);}});Exception e=reject(()->lookup("1080p",0,true));check(calls.size()==1&&eligible(e),"fresh empty lookup is caller-retryable once");check(!PlaybackSources.canLowerQuality(e),"empty lookup does not change manual quality contract");});
   group("business malformed TLS and cancellation remain terminal",()->{for(String code:new String[]{"BUSINESS_REJECTED","APP_INVALID_RESPONSE"}){callback(a->{try{PlaybackSources.result(envelope(a).put("error","fixture terminal").put("errorCode",code));}catch(Exception e){throw new RuntimeException(e);}});check(!eligible(reject(()->lookup("1080p",0,true))),"terminal lookup code");}for(Exception e:new Exception[]{new javax.net.ssl.SSLHandshakeException("cert"),new InterruptedIOException("cancel"),new JSONException("metadata"),new IllegalArgumentException("input"),new IOException("identity invalid")})check(!eligible(e),"terminal class "+e.getClass().getSimpleName());});
   group("fresh lookup failure never returns registered old Plan",()->{PlaybackSources.Plan old=PlaybackSources.register(model("720p",720,1079),VID,false);callback(a->{try{PlaybackSources.result(envelope(a).put("error","temporary miss").put("errorCode","ETIMEDOUT"));}catch(Exception e){throw new RuntimeException(e);}});check(eligible(reject(()->lookup("720p",1079,true))),"fresh lookup throws temporary failure, not previous URL");check(old.url.equals(URL),"old object is not mutated for unrelated jobs");});
   group("media refresh retains exact playback cap across the existing HTTP403 recovery",()->{NetworkGuard.reset();JSONObject p=model("720p",720,1079);PlaybackSources.register(p,VID,false);NetworkGuard.outcomes.put(URL,"http403");int[]calls={0};callback(a->{try{calls[0]++;check(a.length()==5&&a.getInt(4)==1079,"media relookup cap survives");PlaybackSources.result(envelope(a).put("playInfo",model("720p",720,1079).put("url",URL+"?fresh")));}catch(Exception e){throw new RuntimeException(e);}});File temp=File.createTempFile("playback-resolution-", ".part");temp.delete();try{PlaybackSources.download(URL,temp,64,"720p");check(calls[0]==1&&temp.isFile()&&temp.length()>0,"fresh bounded candidate publishes real fixture bytes");}finally{temp.delete();}});
   group("invalid boundary rejects before pending callback",()->{int[]calls={0};callback(a->{calls[0]++;success(a,720);});reject(()->lookup("720p",-1,true));reject(()->lookup("720p",16385,true));check(calls[0]==0,"invalid boundary performs zero work");});
   System.out.println("PLAYBACK_RESOLUTION_NATIVE_OK groups="+groups+" checks="+checks+" actualPlan=true freshOpaqueRequests=true networkRequests=0");
  }finally{PlaybackSources.detach(host);Thread.interrupted();}
 }
}
